$form.ForeColor       = $TEXT
$form.FormBorderStyle = "None"
$form.MaximizeBox     = $false
$form.Font            = $FontSub

$script:_drag = $false
$script:_dragStart = [System.Drawing.Point]::Empty
$form.Add_MouseDown({ param($s,$e)
    if ($e.Button -eq [System.Windows.Forms.MouseButtons]::Left) {
        $script:_drag = $true; $script:_dragStart = $e.Location
    }
})
$form.Add_MouseMove({ param($s,$e)
    if ($script:_drag) {
        $form.Left += $e.X - $script:_dragStart.X
        $form.Top  += $e.Y - $script:_dragStart.Y
    }
})
$form.Add_MouseUp({ $script:_drag = $false })

$form.Add_Paint({
    $g = $_.Graphics
    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    [int]$fw = $form.Width; [int]$fh = $form.Height

    # กรอบนอกเรืองแสง
    for ($i = 0; $i -lt 3; $i++) {
        $a = 90 - ($i * 25)
        $pen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb($a, 190, 100, 255), (1 + $i))
        $g.DrawRectangle($pen, $i, $i, ($fw - 1 - $i*2), ($fh - 1 - $i*2))
        $pen.Dispose()
    }

    # แถบไล่สีบนสุด
    $pt1 = New-Object System.Drawing.Point(0, 0)
    $pt2 = New-Object System.Drawing.Point($fw, 0)
    $br = New-Object System.Drawing.Drawing2D.LinearGradientBrush($pt1, $pt2, $ACCENT, $ACCENT3)
    $g.FillRectangle($br, 0, 0, $fw, 3); $br.Dispose()

    # เส้นทแยงมุมตกแต่งซ้ายบน-ขวาล่าง (สไตล์ HUD)
    $diagPen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(35, 130, 55, 230), 1)
    for ($x = -$fh; $x -lt $fw; $x += 40) {
        $g.DrawLine($diagPen, $x, 0, ($x + $fh), $fh)
    }
    $diagPen.Dispose()
})

