# ===================== STAGE RAIL  =====================
$railPanel = New-Object System.Windows.Forms.Panel
$railPanel.Location  = New-Object System.Drawing.Point(14, 100)
$railPanel.Size      = New-Object System.Drawing.Size(70, 460)
$railPanel.BackColor = [System.Drawing.Color]::Transparent
$form.Controls.Add($railPanel)

$stepDefs = @(
    @{ id=1; label="REG EDIT"  },
    @{ id=2; label="NETWORK"   },
    @{ id=3; label="OPTIMIZE"  },
    @{ id=4; label="BRYCE PRF" },
    @{ id=5; label="GPU"       },
    @{ id=6; label="CPU"       }
)
$stepState = @{}
foreach ($s in $stepDefs) { $stepState[$s.id] = "idle" }

$railPanel.Add_Paint({
    $g = $_.Graphics
    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    [int]$rw = $railPanel.Width

    $n = $stepDefs.Count
    $stepH = 460 / $n
    $cx = [int]($rw / 2)

    # เส้นเชื่อมแนวตั้ง
    $linePen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(50, 185, 70, 255), 2)
    $g.DrawLine($linePen, $cx, 20, $cx, (460 - 20))
    $linePen.Dispose()

    for ($i = 0; $i -lt $n; $i++) {
        $id = $stepDefs[$i].id
        $cy = [int](20 + $i * $stepH + ($stepH/2) - $stepH/2 + 18)
        $state = $stepState[$id]

        $ringColor = switch ($state) {
            "active" { $ACCENT }
            "done"   { $DARKRED }
            default  { [System.Drawing.Color]::FromArgb(80, 90, 90, 90) }
        }
        $fillColor = switch ($state) {
            "active" { [System.Drawing.Color]::FromArgb(180, 185, 70, 255) }
            "done"   { [System.Drawing.Color]::FromArgb(140, 55, 20, 80) }
            default  { [System.Drawing.Color]::FromArgb(20, 20, 20) }
        }

        $r = 14
        $rect = New-Object System.Drawing.Rectangle(($cx - $r), ($cy - $r), ($r*2), ($r*2))
        $fb = New-Object System.Drawing.SolidBrush($fillColor)
        $g.FillEllipse($fb, $rect); $fb.Dispose()
        $rp = New-Object System.Drawing.Pen($ringColor, 2)
        $g.DrawEllipse($rp, $rect); $rp.Dispose()

        $txtBrush = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::White)
        $fmt = New-Object System.Drawing.StringFormat
        $fmt.Alignment = "Center"; $fmt.LineAlignment = "Center"
        $rectF = New-Object System.Drawing.RectangleF($rect.X, $rect.Y, $rect.Width, $rect.Height)
        $g.DrawString("$id", $FontMono, $txtBrush, $rectF, $fmt)
        $txtBrush.Dispose(); $fmt.Dispose()
    }
})

function Update-Rail { $railPanel.Invalidate() }

