try {
    $osInfo  = (Get-CimInstance Win32_OperatingSystem).Caption
    $cpuInfo = (Get-CimInstance Win32_Processor).Name
    $ramGB   = [math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1GB, 1)
} catch {
    $osInfo = "Windows"; $cpuInfo = "Unknown CPU"; $ramGB = "?"
}

$sInfoItems = @(
    @{ key="OS";  val=$osInfo },
    @{ key="CPU"; val=$cpuInfo },
    @{ key="RAM"; val="${ramGB} GB" }
)
$sX = 16
$colWidths = @(210, 260, 90)
$ci = 0
foreach ($si in $sInfoItems) {
    $lk = New-Object System.Windows.Forms.Label
    $lk.Text = $si.key; $lk.Font = New-Object System.Drawing.Font("Consolas", 7, [System.Drawing.FontStyle]::Bold)
    $lk.ForeColor = $ACCENT3
    $lk.Location = New-Object System.Drawing.Point($sX, 8)
    $lk.Size = New-Object System.Drawing.Size($colWidths[$ci], 16)
    $statsPanel.Controls.Add($lk)
    $lv = New-Object System.Windows.Forms.Label
    $lv.Text = $si.val; $lv.Font = New-Object System.Drawing.Font("Consolas", 7.5)
    $lv.ForeColor = $TEXT
    $lv.Location = New-Object System.Drawing.Point($sX, 24)
    $lv.Size = New-Object System.Drawing.Size($colWidths[$ci], 18)
    $statsPanel.Controls.Add($lv)
    $sX += $colWidths[$ci] + 6
    $ci++
}

