function Write-Log {
    param([string]$msg, [string]$type = "info")
    try {
        $col = switch ($type) {
            "ok"    { [System.Drawing.Color]::FromArgb(220, 150, 255) }
            "warn"  { [System.Drawing.Color]::FromArgb(230, 170, 255) }
            "err"   { [System.Drawing.Color]::FromArgb(220, 180, 255) }
            "dim"   { [System.Drawing.Color]::FromArgb(100, 65, 130) }
            "hi"    { [System.Drawing.Color]::FromArgb(245, 225, 255) }
            "step"  { [System.Drawing.Color]::FromArgb(190, 100, 255) }
            default { [System.Drawing.Color]::FromArgb(205, 175, 225) }
        }
        $ts = (Get-Date).ToString("HH:mm:ss")
        $logBox.SelectionStart  = $logBox.TextLength
        $logBox.SelectionColor  = [System.Drawing.Color]::FromArgb(100, 65, 130)
        $logBox.AppendText("[$ts] ")
        $logBox.SelectionColor  = $col
        $logBox.AppendText("$msg`n")
        $logBox.ScrollToCaret()
        [System.Windows.Forms.Application]::DoEvents()
    } catch { }
}

# ===================== RADIAL PROGRESS RING =====================
$ringPanel = New-Object System.Windows.Forms.Panel
$ringPanel.Location  = New-Object System.Drawing.Point(672, 100)
$ringPanel.Size      = New-Object System.Drawing.Size(294, 294)
$ringPanel.BackColor = $BG2
$form.Controls.Add($ringPanel)

$ringPanel.Add_Paint({
    $g = $_.Graphics
    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    [int]$rw = $ringPanel.Width; [int]$rh = $ringPanel.Height

    $p = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(75, 190, 100, 255), 1)
    $g.DrawRectangle($p, 0, 0, ($rw-1), ($rh-1)); $p.Dispose()

    # Aizen image backdrop
    if ($script:aizenImage -ne $null) {
        $imgRect = New-Object System.Drawing.Rectangle(2, 2, ($rw - 4), ($rh - 4))
        $g.DrawImage($script:aizenImage, $imgRect)
        $shade = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(105, 5, 2, 12))
        $g.FillRectangle($shade, $imgRect)
        $shade.Dispose()
    }

    $margin = 40
    $rect = New-Object System.Drawing.Rectangle($margin, $margin, ($rw - $margin*2), ($rh - $margin*2))

    # วงพื้นหลัง
    $bgPen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(50, 55, 20, 80), 14)
    $g.DrawEllipse($bgPen, $rect); $bgPen.Dispose()

    # วง progress (arc)
    $sweep = 360 * ($script:progressValue / 100)
    if ($sweep -gt 0) {
        $fgPen = New-Object System.Drawing.Pen($ACCENT, 14)
        $fgPen.StartCap = [System.Drawing.Drawing2D.LineCap]::Round
        $fgPen.EndCap   = [System.Drawing.Drawing2D.LineCap]::Round
        $g.DrawArc($fgPen, $rect, -90, $sweep)
        $fgPen.Dispose()
    }

    # ข้อความเปอร์เซ็นต์ตรงกลาง
    $txt = "$($script:progressValue)%"
    $txtBrush = New-Object System.Drawing.SolidBrush($TEXT)
    $fmt = New-Object System.Drawing.StringFormat
    $fmt.Alignment = "Center"; $fmt.LineAlignment = "Center"
    $rectF = New-Object System.Drawing.RectangleF($rect.X, $rect.Y, $rect.Width, $rect.Height)
    $g.DrawString($txt, $FontBig, $txtBrush, $rectF, $fmt)
    $txtBrush.Dispose(); $fmt.Dispose()

    # label ด้านล่างวง
    $lblBrush = New-Object System.Drawing.SolidBrush($ACCENT2)
    $fmt2 = New-Object System.Drawing.StringFormat
    $fmt2.Alignment = "Center"
    $g.DrawString("PROGRESS", $FontMono, $lblBrush, ($rw/2), ($rh - 24), $fmt2)
    $lblBrush.Dispose(); $fmt2.Dispose()
})

function Set-Progress {
    param([int]$val, [string]$task = "")
    $script:progressValue = [Math]::Max(0, [Math]::Min($val, 100))
    $ringPanel.Invalidate()
    if ($task) { $lblTask.Text = $task }
    [System.Windows.Forms.Application]::DoEvents()
}

