function New-MiniButton {
    param($txt, $x, $y, $w, $h, $fc)
    $b = New-Object System.Windows.Forms.Button
    $b.Text = $txt
    $b.Location = New-Object System.Drawing.Point($x, $y)
    $b.Size = New-Object System.Drawing.Size($w, $h)
    $b.FlatStyle = "Flat"
    $b.FlatAppearance.BorderColor = $fc
    $b.FlatAppearance.BorderSize = 1
    $b.FlatAppearance.MouseOverBackColor = [System.Drawing.Color]::FromArgb(30, $fc.R, $fc.G, $fc.B)
    $b.BackColor = [System.Drawing.Color]::FromArgb(8, 4, 14)
    $b.ForeColor = $fc
    $b.Font = New-Object System.Drawing.Font("Consolas", 8, [System.Drawing.FontStyle]::Bold)
    $b.Cursor = [System.Windows.Forms.Cursors]::Hand
    return $b
}

