# ===================== HELPERS =====================
function Set-StepActive {
    param([int]$active)
    foreach ($s in $stepDefs) {
        if ($s.id -eq $active)      { $stepState[$s.id] = "active" }
        elseif ($s.id -lt $active)  { $stepState[$s.id] = "done" }
        else                        { $stepState[$s.id] = "idle" }
    }
    Update-Rail
    [System.Windows.Forms.Application]::DoEvents()
}

